dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "Mixed",
          "value": "mixed"
        },
        {
          "label": "EU",
          "value": "eu"
        }
      ]
    },
    {
      "parameter": "gene",
      "label": "Phenotypes by Gene",
      "type": "input",
      "values": "kp genes"
    },
    {
      "parameter": "phenotype",
      "label": "Phenotype for Associations",
      "type": "input",
      "display": "false"
    }
  ],
  "tab groups": [
    [
      {
        "section": "traitsByGene",
        "label": "Phenotypes by Gene"
      },
      {
        "section": "traitsList",
        "label": "Phenotypes Full List"
      }
    ]
  ],
  "sections": [
    {
      "section id": "traitsList",
      "header": "Phenotypes List",
      "data point": {
        "type": "file",
        "file": "600Traits.csv",
        "data type": "csv"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "Phecode"
          },
          {
            "type": "raw",
            "field name": "Set Phenotype",
            "raw field": "Phecode"
          },
          {
            "type": "replace characters",
            "field name": "Meaning",
            "raw field": "Phecode_Meaning",
            "replace": [
              {
                "from": "_",
                "to": " "
              }
            ]
          },
          {
            "type": "replace characters",
            "field name": "Category",
            "raw field": "Phecode_Category",
            "replace": [
              {
                "from": "_",
                "to": " "
              }
            ]
          }
        ],
        "column formatting": {
          "Set Phenotype": {
            "type": [
              "set parameter"
            ],
            "parameter": "phenotype"
          }
        },
        "top rows": [
          "Phenotype",
          "Meaning",
          "Category",
          "Set Phenotype"
        ]
      },
      "filters": [
        {
          "field": "Phenotype",
          "label": "Phenotype code",
          "type": "search"
        },
        {
          "field": "Meaning",
          "label": "Meaning",
          "type": "search"
        },
        {
          "field": "Category",
          "label": "Category",
          "type": "dropdown"
        }
      ]
    },
    {
      "section id": "traitsByGene",
      "header": "Phenotypes List by Gene",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "gene-associations-600trait",
        "parameters": [
          "ancestry",
          "gene"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Set Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "replace characters",
            "field name": "Meaning",
            "raw field": "phenotypeMeaning",
            "replace": [
              {
                "from": "_",
                "to": " "
              }
            ]
          },
          {
            "type": "replace characters",
            "field name": "Category",
            "raw field": "phenotypeCategory",
            "replace": [
              {
                "from": "_",
                "to": " "
              }
            ]
          },
          {
            "type": "kp phenotype name",
            "field name": "Phenotype name",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "ID",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "Masks",
            "raw field": "masks"
          },
          {
            "type": "raw",
            "field name": "Mask",
            "raw field": "mask"
          },
          {
            "type": "raw",
            "field name": "Effective Sample Size",
            "raw field": "n"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Combined AF",
            "raw field": "combinedAF"
          },
          {
            "type": "raw",
            "field name": "Cases",
            "raw field": "cases"
          },
          {
            "type": "raw",
            "field name": "Controls",
            "raw field": "controls"
          }
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation",
              "render background percent negative"
            ],
            "percent if empty": 1
          },
          "Beta": {
            "type": [
              "fixed 4",
              "direction triangle"
            ]
          },
          "Effective Sample Size": {
            "type": [
              "js math"
            ],
            "method": "round"
          },
          "Combined AF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Set Phenotype": {
            "type": [
              "set parameter"
            ],
            "parameter": "phenotype"
          }
        },
        "top rows": [
          "Phenotype",
          "Category",
          "Meaning",
          "P-Value",
          "Beta",
          "Set Phenotype"
        ],
        "features": [
          "Masks"
        ],
        "Masks": [
          "Mask",
          "P-Value",
          "Combined AF",
          "Standard Error",
          "Effective Sample Size",
          "Cases",
          "Controls",
          "Beta"
        ]
      },
      "filters": [
        {
          "field": "Phenotype name",
          "label": "Phenotype",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "Meaning",
          "label": "Meaning",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "Category",
          "label": "Category",
          "type": "dropdown",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (<=)",
          "type": "search lower than",
          "label in bubble": "true"
        }
      ],
      "visualizers": {
        "wrapper type": "tabs",
        "visualizers": [
          {
            "label": "Plot 1",
            "type": "phewas plot",
            "group by": "Category",
            "y axis field": "P-Value",
            "convert y -log10": "true",
            "y ticks decimal point": "2",
            "render by": "Meaning",
            "y axis label": "-Log10(p-value)",
            "x axis label": "Beta",
            "beta field": "Beta",
            "hover content": [
              "P-Value",
              "Beta"
            ],
            "thresholds": [
              "2.5e-6"
            ],
            "height": 500,
            "star key": "Phenotype",
            "plot margin": {
              "top": 300,
              "bottom": 200,
              "left": 150,
              "right": 175
            }
          },
          {
            "label": "Plot 2",
            "type": "phewas plot",
            "group by": "Category",
            "y axis field": "P-Value",
            "convert y -log10": "true",
            "y ticks decimal point": "2",
            "render by": "Meaning",
            "y axis label": "-Log10(p-value)",
            "x axis label": "Beta",
            "beta field": "Beta",
            "hover content": [
              "P-Value",
              "Beta"
            ],
            "thresholds": [
              "2.5e-6"
            ],
            "height": 500,
            "star key": "Phenotype",
            "plot margin": {
              "top": 300,
              "bottom": 200,
              "left": 150,
              "right": 175
            }
          }
        ]
      }
    },
    {
      "section id": "associations",
      "header": "Phenotype Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://bioindex.hugeamp.org/api/bio/",
        "index": "gene-finder-600trait",
        "parameters": [
          "ancestry",
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "lambda",
            "raw field": "lambda"
          },
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Set Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "View (Mixed)",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "View (EU)",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Type",
            "raw field": "type"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "Log10PValue",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Cases",
            "raw field": "cases"
          },
          {
            "type": "raw",
            "field name": "Controls",
            "raw field": "controls"
          }
        ],
        "column formatting": {
          "Gene": {
            "type": [
              "link"
            ],
            "link to": "/research.html?pageid=600_diseases_gene&gene="
          },
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Set Gene": {
            "type": [
              "set parameter"
            ],
            "parameter": "gene"
          }
        },
        "top rows": [
          "Gene",
          "Region",
          "P-Value",
          "Type",
          "Cases",
          "Controls"
        ],
        "tool tips": {
          "Gene": "Click a gene name to see all associations for that gene",
          "Region": "Chromosome and coordinates of the gene",
          "P-Value": "p-value of the gene-level association",
          "Type": "Type of the gene",
          "Phenotype meaning": "Description of the phenotype",
          "Phenotype category": "Broad grouping for the phenotype"
        },
        "locus field": "Region"
      },
      "visualizer": {
        "type": "manhattan qq plot",
        "x axis field": "Region",
        "y axis field": "Log10PValue",
        "render by": "Gene",
        "m-plot y axis label": "-Log10(P-Value)",
        "m-plot x axis label": "Chromosome",
        "m-plot thresholds": [
          "2.5e-6"
        ],
        "qq-plot y axis label": "-Log10(P-Value)",
        "qq-plot x axis label": "Expected -Log10(P-Value)",
        "hover content": [
          "Region",
          "P-Value"
        ],
        "height": 150
      }
    }
  ]
}
